#!/bin/bashecho "=========================================="echo " iPHAsimulator Cluster Environment Check"echo "=========================================="echoecho "=== Python ==="which pythonpython --versionechoecho "=== Conda Environment ==="echo "CONDA_PREFIX=$CONDA_PREFIX"echoecho "=== Package import ==="python - <<'EOF'import iphasimulatorprint("iphasimulator:", iphasimulator.__file__)EOFechoecho "=== Core Python packages ==="python - <<'EOF'packages = [    "numpy",    "scipy",    "pandas",    "rdkit",    "openmm",    "parmed",    "MDAnalysis",]for package in packages:    try:        __import__(package)        print(f"✓ {package}")    except Exception as e:        print(f"✗ {package}: {e}")EOFechoecho "=== AmberTools executables ==="for exe in \    tleap \    antechamber \    parmchk2 \    prepgen \    acpypedo    printf "%-15s" "$exe"    which "$exe"doneechoecho "=== Polyply ==="which polyplypolyply --versionechoecho "=== OpenMM Platforms ==="python - <<'EOF'from openmm import Platformfor i in range(Platform.getNumPlatforms()):    p = Platform.getPlatform(i)    print("-", p.getName())EOFechoecho "=== CUDA test ==="python - <<'EOF'from openmm import Platformtry:    p = Platform.getPlatformByName("CUDA")    print("CUDA available")    print("Device:", p.getPropertyDefaultValue("DeviceIndex"))except Exception as e:    print("CUDA unavailable")    print(e)EOFechoecho "=== Repository import test ==="python - <<'EOF'from iphasimulator.build_pha import PHAPolymerBuilderfrom iphasimulator.pha_melt_builder import PHAMeltBuilderfrom iphasimulator.sw_openmm import AmberSimulationprint("All major imports successful.")EOFechoecho "=========================================="echo " Environment check complete"echo "=========================================="